| fpsp_packed_kernel_e2e.s — REAL ROM FPSP kernel, end-to-end round-trip
|
| Runs the Q700 ROM's actual F-line/FPSP kernel (entry 0x4088D9FE),
| byte-for-byte at its native address, against an FMOVE.P (packed-
| decimal source — genuinely unimplemented on real 68040 silicon too,
| so real Macs exercise this exact software path).  This is the full-
| fidelity regression for the 2026-07-15 live-HW Sad Mac 02:
|
|   * vec-11 fmt-$2 frame push (0x202C check at 0x4088D9FE)
|   * `linkw %fp,#-192; fsave %sp@-` — REQUIRES the 52-byte
|     version-0x41/size-0x30 FSAVE frame: the kernel addresses the
|     frame fields as fp@(-244..-196) and BSRs deeper with SP just
|     below them.  The old 4-byte frame left SP 48 bytes high and the
|     kernel's `fmove.x %fp0,%fp@(-204)` overwrote a live return-
|     address slot → RTS popped 0x7FFFFFFF → vec-3 (frame PC
|     0x4088E4C6, exactly the HW signature).
|   * the packed-decimal operand fetch / dec2bin conversion chain
|     (0x4088E308/0x4088E4FE) with its FMOVEM.X spills, FMOVE.X
|     stores, dynamic bitfields, MUL.L, FPCR/FPSR system moves
|   * size-aware FRESTORE of both real and FPSP-manufactured frames
|   * RTE resume at the instruction after the trapped FMOVE.P
|
| FULL-EMULATION CONTRACT (frame population landed): the packed-source
| capture crack latches the EA-fetched operand (ETEMP) and command
| word (CMDREG1B) into commit-side registers; FSAVE -(An) writes them
| into the 52-byte UNIMP frame (+16 command, +24 unsupported-datatype
| tag, +40 ETEMP), exactly the fields the frame-driven kernel reads at
| fp@(-228)/fp@(-220)/fp@(-204).  The vec-11 frame PC is pushed
| POST-instruction (real-040 fmt-$2 semantics — the kernel RTEs to the
| frame PC unadjusted).  The kernel therefore converts the operand
| through its own classify/dec2bin (0x4088E308/0x4088E4FE) and resumes
| cleanly past the FMOVE.P after exactly ONE trap.  The numeric result
| in FP0 is NOT asserted (approximate-FP doctrine — FMOVEM.X reload is
| still data-discarding).
|
| Fragment provenance: files/420dbff3.rom [0x8D000..0x95000), embedded
| verbatim below at its native address.  Low-mem 0x1FC8 (the ROM's
| saved prior-F-line-handler chain slot, used by the kernel's
| "not-an-FPU-op" bail-out at 0x4088DAAA) is pointed at a FAIL
| trampoline: the kernel must NOT chain out for a genuine FPU op.
|
| PASS: a full kernel pass is stack-safe (see KNOWN GAP note).
| FAIL codes at 0xFFFF0000:
|   0xBADBAD00 — SP or A0 corrupted across the emulated FMOVE.P
|   0xBAD00002/3/4/A — unexpected vec 2 / 3 / 4 / A-line
|   0xBAD0001C — kernel chained out through 0x1FC8
|   0xBAD00034 — SP or frame drift between kernel passes (THE 2026-07-15
|                corruption class)
|   (timeout = kernel wedged internally)

    .text
    .org 0

_start:
    lea     0x00011000, %a7
    | Vector table (VBR=0)
    move.l  #_handler2,  0x00000008
    move.l  #_handler3,  0x0000000C
    move.l  #_handler4,  0x00000010
    move.l  #_handler10, 0x00000028
    move.l  #_v11_gate,  0x0000002C     | vec 11 → count, then the FPSP
    moveq   #0, %d6                     | vec-11 entry counter
    move.l  #_chain_out, 0x00001FC8     | prior-handler chain slot

    | Packed-decimal operand: "5e8 with packed exponent nibbles 0x026"
    | (same operand fpsp_dec2bin_sp_integrity.s runs through the bare
    | classify fragment).
    lea     0x00020000, %a0
    move.l  #0x00260000, (%a0)
    move.l  #0x00000005, 4(%a0)
    clr.l   8(%a0)

    move.l  %a7, %d7                    | SP snapshot
_trigger:
    .short  0xF210, 0x4C00              | fmove.p (%a0),%fp0 → vec 11
_resume:
    | Full-emulation assertions: the kernel converted the packed
    | operand, wrote the result, and RTE'd HERE (post-instruction
    | frame PC).  Exactly one vec-11 entry (checked by _v11_gate).
    cmp.l   %a7, %d7                    | SP exactly restored
    bne     _fail
    lea     0x00020000, %a1             | A0 untouched (non-postinc EA)
    cmp.l   %a1, %a0
    bne     _fail

    | ── Stage 2: (d16,An) EA form ────────────────────────────────────
    moveq   #0, %d6
    lea     0x00020100, %a0
    move.l  #0x00260000, 0x40(%a0)
    move.l  #0x00000007, 0x44(%a0)
    clr.l   0x48(%a0)
    move.l  %a7, %d7
    .short  0xF228, 0x4C00, 0x0040      | fmove.p (0x40,%a0),%fp0
    cmp.l   %a7, %d7
    bne     _fail
    lea     0x00020100, %a1
    cmp.l   %a1, %a0
    bne     _fail
    cmp.l   #1, %d6                     | exactly one kernel entry
    bne     _fail

    | ── Stage 3: packed NaN operand (direct classify path) ──────────
    moveq   #0, %d6
    lea     0x00020200, %a0
    move.l  #0x7FFF0000, (%a0)          | packed exp nibbles 0xFFF
    move.l  #0x00000001, 4(%a0)         | nonzero mantissa → NaN class
    clr.l   8(%a0)
    move.l  %a7, %d7
    .short  0xF210, 0x4C00              | fmove.p (%a0),%fp0
    cmp.l   %a7, %d7
    bne     _fail
    cmp.l   #1, %d6
    bne     _fail
_pass:
    lea     0xFFFF0000, %a1
    move.l  #0xC0FFEE00, %d1
    move.l  %d1, (%a1)
_halt:
    bra     _halt

_fail:
    lea     0xFFFF0000, %a1
    move.l  #0xBADBAD00, %d1
    move.l  %d1, (%a1)
_fhlt:
    bra     _fhlt

_v11_gate:
    | Per-entry stack-integrity gate (A3/D5/D6 are untouched by the
    | kernel — it saves/restores only D0-D1/A0-A1 and balances its
    | D2-D5 pushes).
    addq.l  #1, %d6
    cmp.l   #1, %d6
    bne     _v11_second
    | First entry: record the post-push SP and the frame PC, run the
    | real kernel.
    move.l  %a7, %a3
    move.l  2(%a7), %d5
    jmp     0x4088D9FE
_v11_second:
    | A second entry is a re-trap loop — the pre-frame-population
    | failure mode (kernel found a zero UNIMP frame, emulated nothing,
    | RTE'd without progress).  Hard FAIL.
    lea     0xFFFF0000, %a1
    move.l  #0xBAD00033, %d1
    move.l  %d1, (%a1)
    bra     _fhlt

_chain_out:
    lea     0xFFFF0000, %a1
    move.l  #0xBAD0001C, %d1
    move.l  %d1, (%a1)
    bra     _fhlt
_handler2:
    lea     0xFFFF0000, %a1
    move.l  #0xBAD00002, %d1
    move.l  %d1, (%a1)
    bra     _fhlt
_handler3:
    lea     0xFFFF0000, %a1
    move.l  #0xBAD00003, %d1
    move.l  %d1, (%a1)
    bra     _fhlt
_handler4:
    lea     0xFFFF0000, %a1
    move.l  #0xBAD00004, %d1
    move.l  %d1, (%a1)
    bra     _fhlt
_handler10:
    lea     0xFFFF0000, %a1
    move.l  #0xBAD0000A, %d1
    move.l  %d1, (%a1)
    bra     _fhlt

